def _parse(blob):
    out = {}
    for line in blob.splitlines():
        line = line.strip()
        if not line:
            continue
        head, _, body = line.partition("|")
        rows = {}
        for cell in body.split():
            tile, row, mapno = (int(x) for x in cell.split(":"))
            rows[tile] = (row, mapno)
        out[int(head)] = rows
    return out


SECTORS = _parse(_TABLE)


def battle_map_for(selector, tile):
    """(row, battle map id) for one war-map sector, or None.

    None means "this pair is not in SE's table" and is a different answer
    from a row whose map is 2/3/4/5 -- that one IS in the table and simply
    has no battlefield. Callers must keep the two apart: the first is us not
    knowing, the second is the game saying no.
    """
    return SECTORS.get(int(selector), {}).get(int(tile))


def sector_count(selector):
    """How many sectors a selector has, for logging a lookup miss usefully."""
    return len(SECTORS.get(int(selector), {}))
